import java.util.LinkedHashSet;
import java.util.SequencedSet;

public class SequencedDemo {
    public static void main(String[] args) {
        SequencedSet<String> colors = new LinkedHashSet<>();
        colors.add("Red");
        colors.add("Green");
        colors.add("Blue");

        // Accessing boundaries uniformly
        System.out.println(colors.getFirst()); // Red
        System.out.println(colors.getLast());  // Blue

        // Mutating via boundaries
        colors.addFirst("Yellow");
        System.out.println(colors.getFirst()); // Yellow

        // Iterating in reverse view without copying
        SequencedSet<String> reversedView = colors.reversed();
        reversedView.forEach(System.out::println);
    }
}
